struct Coordinates {
    int x;
    double y = 0.0; // C++11 Default Member Initializer
};

// 1. Aggregate Initialization (C++03/11)
Coordinates c1 = {10, 5.5};

// 2. Uniform Initialization (C++11)
Coordinates c2{20}; // x=20, y=0.0 (default)

// 3. Designated Initializers (C++20)
Coordinates c3{.y = 99.9, .x = 5};

struct UserData {
    int id;
    // Custom Constructor Initialization
    UserData(int i) : id(i) {}
};

UserData u1(42);
